exercises.solution:
class Book:
    def __init__(self, title="", author="", pages=0):
        self.title, self.author, self.pages = title, author, pages
    def __repr__(self):
        sep = "  " if not self.author else f" {self.author} "
        return f"{{{self.title}{sep}{self.pages}}}"

print(Book(title="Go Programming"))

